package com.trampolim.api.career;
import java.util.*;import java.time.*;import java.security.SecureRandom;
import static com.trampolim.api.radar.RadarModel.*;import com.trampolim.api.radar.*;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service @ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class CompanySelectionService {
 private final JdbcTemplate jdbc;private final CompanyCareerService companies;private final RadarBridge bridge;
 public CompanySelectionService(@Qualifier("empresasJdbcTemplate")JdbcTemplate jdbc,CompanyCareerService companies,RadarBridge bridge){this.jdbc=jdbc;this.companies=companies;this.bridge=bridge;}
 public record Outcome(UUID requestKey,Instant interviewAt,boolean interviewHeld,LocalDate hireDate){}public record Confirmation(int version,String code,String candidateEmail,boolean consent,boolean publicMetricsConsent){}
 public List<Map<String,Object>> applications(String email){long company=companies.member(email,true);return jdbc.queryForList("SELECT a.id,a.candidate_name,l.title,o.id AS outcome_id,o.interview_at,o.interview_held,o.hire_date,o.candidate_confirmed_at FROM company_applications a JOIN company_listings l ON l.id=a.listing_id LEFT JOIN company_selection_outcomes o ON o.application_id=a.id WHERE l.company_id=? ORDER BY a.id DESC LIMIT 100",company);}
 @Transactional("empresasTransactionManager")public Map<String,Object> record(String email,long application,Outcome input){long company=companies.member(email,true);if(input==null||input.requestKey()==null||input.interviewAt()==null&&input.hireDate()==null||input.interviewHeld()&&(input.interviewAt()==null||input.interviewAt().isAfter(Instant.now()))||input.hireDate()!=null&&input.hireDate().isAfter(LocalDate.now(ZoneId.of("America/Sao_Paulo"))))bad("Informe entrevista ou contratação já ocorrida; agendamento não equivale a entrevista realizada.");var app=jdbc.queryForList("SELECT a.created_at FROM company_applications a JOIN company_listings l ON l.id=a.listing_id WHERE a.id=? AND l.company_id=? FOR UPDATE OF a",application,company);if(app.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);if(input.hireDate()!=null&&input.hireDate().isBefore(((java.sql.Timestamp)app.get(0).get("created_at")).toLocalDateTime().toLocalDate()))bad("A contratação não pode anteceder a candidatura registrada.");String hash=RadarBridge.hash(bridge.encode(input));var previous=jdbc.queryForList("SELECT * FROM company_selection_outcomes WHERE application_id=?",application);if(!previous.isEmpty()){var old=previous.get(0);if(old.get("request_key").equals(input.requestKey())){if(!old.get("request_hash").equals(hash))throw new ResponseStatusException(HttpStatus.CONFLICT,"Identificação do pedido já usada com outros dados.");return Map.of("id",old.get("id"),"status",old.get("candidate_confirmed_at")==null?"REPORTED_BY_COMPANY":"CONFIRMED_BY_CANDIDATE");}if(old.get("candidate_confirmed_at")!=null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Resultado confirmado preservado para auditoria; solicite revisão administrativa para corrigir.");}
  UUID id=previous.isEmpty()?UUID.randomUUID():(UUID)previous.get(0).get("id");String code="";if(input.hireDate()!=null){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);code=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}jdbc.update("INSERT INTO company_selection_outcomes(id,application_id,interview_at,interview_held,hire_date,confirmation_hash,confirmation_expires_at,request_key,request_hash) VALUES (?,?,?,?,?,?,CASE WHEN ? THEN CURRENT_TIMESTAMP+INTERVAL '30 days' ELSE NULL END,?,?) ON CONFLICT(application_id) DO UPDATE SET interview_at=EXCLUDED.interview_at,interview_held=EXCLUDED.interview_held,hire_date=EXCLUDED.hire_date,confirmation_hash=EXCLUDED.confirmation_hash,confirmation_expires_at=EXCLUDED.confirmation_expires_at,request_key=EXCLUDED.request_key,request_hash=EXCLUDED.request_hash,updated_at=CURRENT_TIMESTAMP",id,application,input.interviewAt()==null?null:java.sql.Timestamp.from(input.interviewAt()),input.interviewHeld(),input.hireDate(),code.isEmpty()?null:RadarBridge.hash(code),!code.isEmpty(),input.requestKey(),hash);companies.audit(company,email,"CAREER_SELECTION_REPORTED");return Map.of("id",id,"status","REPORTED_BY_COMPANY","confirmationCode",code,"notice","Contratação declarada pela empresa; aguarda confirmação autenticada do candidato. Não é pagamento nem prova de vínculo legal.");}
 private Map<String,Object> lookup(Confirmation input){if(input==null||input.version()!=1||input.code()==null||!input.code().matches("[A-Za-z0-9_-]{43}")||input.candidateEmail()==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);return jdbc.queryForList("SELECT o.id,o.hire_date,o.candidate_confirmed_at,c.trade_name,l.title FROM company_selection_outcomes o JOIN company_applications a ON a.id=o.application_id JOIN company_listings l ON l.id=a.listing_id JOIN companies c ON c.id=l.company_id WHERE o.confirmation_hash=? AND LOWER(a.candidate_email)=LOWER(?) AND o.confirmation_expires_at>CURRENT_TIMESTAMP AND o.hire_date IS NOT NULL",RadarBridge.hash(input.code()),input.candidateEmail()).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Código indisponível ou destinado a outro candidato."));}
 public Map<String,Object> preview(String key,Confirmation input){bridge.authorize(key);return lookup(input);}
 @Transactional("empresasTransactionManager")public Map<String,Object> confirm(String key,Confirmation input){bridge.authorize(key);if(input==null||!input.consent())bad("Confirme expressamente o resultado informado para esta empresa e oportunidade.");var row=lookup(input);jdbc.update("UPDATE company_selection_outcomes SET candidate_confirmed_at=COALESCE(candidate_confirmed_at,CURRENT_TIMESTAMP),public_metrics_consent=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",input.publicMetricsConsent(),row.get("id"));return Map.of("status","CONFIRMED_BY_CANDIDATE","id",row.get("id"));}
 public Map<String,Object> impact(String email){long company=companies.member(email,false);var result=new LinkedHashMap<String,Object>(jdbc.queryForMap("SELECT (SELECT count(*) FROM company_listings WHERE company_id=? AND kind='job') AS registered_vacancies,(SELECT count(*) FROM company_applications a JOIN company_listings l ON l.id=a.listing_id WHERE l.company_id=?) AS applications,(SELECT count(*) FROM company_challenges WHERE company_id=?) AS challenges",company,company,company));result.putAll(jdbc.queryForMap("SELECT count(*) FILTER(WHERE o.interview_at IS NOT NULL) AS interviews_scheduled,count(*) FILTER(WHERE o.interview_held=TRUE) AS interviews_reported_held,count(*) FILTER(WHERE o.hire_date IS NOT NULL) AS hires_reported,count(*) FILTER(WHERE o.candidate_confirmed_at IS NOT NULL) AS hires_confirmed,avg(o.hire_date-p.published_at::date) FILTER(WHERE o.candidate_confirmed_at IS NOT NULL AND p.published_at IS NOT NULL AND o.hire_date>=p.published_at::date) AS average_fill_days FROM company_selection_outcomes o JOIN company_applications a ON a.id=o.application_id JOIN company_listings l ON l.id=a.listing_id LEFT JOIN career_listing_publications p ON p.listing_id=l.id WHERE l.company_id=?",company));result.put("operatingCosts",jdbc.queryForList("SELECT month,amount_cents,source FROM company_operating_costs WHERE company_id=? ORDER BY month DESC LIMIT 12",company));result.put("retention",null);result.put("notice","Entrevistas realizadas são relatos empresariais. Contratações confirmadas exigem confirmação autenticada do candidato. Tempo de preenchimento só usa data de publicação efetivamente registrada após esta versão; não usa criação como substituto. Permanência não possui fonte confirmada. Custos são registros administrativos informados, não cobrança.");return result;}
}
